class Solution:
    def maxScore(self, grid: list[list[int]]) -> int:
        m = len(grid)
        has = {}
        for i, row in enumerate(grid):
            for v in row:
                has.setdefault(v, set()).add(i)
        FULL = 1 << m
        dp = [-1] * FULL
        dp[0] = 0
        for v, rows in has.items():
            nd = dp[:]
            for mask in range(FULL):
                if dp[mask] < 0:
                    continue
                for r in rows:
                    if not mask >> r & 1:
                        nm = mask | 1 << r
                        if dp[mask] + v > nd[nm]:
                            nd[nm] = dp[mask] + v
            dp = nd
        return max(dp)

