class Solution {
public:
    int maxScore(vector<vector<int>>& grid) {
        int m = grid.size();
        unordered_map<int, vector<int>> has;
        for (int i = 0; i < m; i++)
            for (int v : grid[i]) has[v].push_back(i);
        int FULL = 1 << m;
        vector<int> dp(FULL, -1);
        dp[0] = 0;
        for (auto& [v, rows] : has) {
            vector<int> nd = dp;
            for (int mask = 0; mask < FULL; mask++) {
                if (dp[mask] < 0) continue;
                for (int r : rows)
                    if (!(mask >> r & 1)) {
                        int nm = mask | 1 << r;
                        nd[nm] = max(nd[nm], dp[mask] + v);
                    }
            }
            dp = nd;
        }
        return *max_element(dp.begin(), dp.end());
    }
};

