class Solution {
    public int maxScore(List<List<Integer>> grid) {
        int m = grid.size();
        Map<Integer, List<Integer>> has = new HashMap<>();
        for (int i = 0; i < m; i++)
            for (int v : grid.get(i))
                has.computeIfAbsent(v, k -> new ArrayList<>()).add(i);
        int FULL = 1 << m;
        int[] dp = new int[FULL];
        Arrays.fill(dp, -1);
        dp[0] = 0;
        for (List<Integer> rows : has.values()) {
            int[] nd = dp.clone();
            for (int mask = 0; mask < FULL; mask++) {
                if (dp[mask] < 0) continue;
                for (int r : rows)
                    if ((mask >> r & 1) == 0) {
                        int nm = mask | 1 << r;
                        nd[nm] = Math.max(nd[nm], dp[mask] + rows.get(0) * 0 + gridVal(rows, r));
                    }
            }
            dp = nd;
        }
        int ans = 0;
        for (int x : dp) ans = Math.max(ans, x);
        return ans;
    }
    private int gridVal(List<Integer> rows, int r) { return rows.get(0); }
}

