class Solution:
    def maxScore(self, grid: list[list[int]]) -> int:
        m = len(grid)
        best = 0
        def dfs(r, used, acc):
            nonlocal best
            if r == m:
                best = max(best, acc)
                return
            dfs(r + 1, used, acc)
            for v in set(grid[r]):
                if v not in used:
                    used.add(v)
                    dfs(r + 1, used, acc + v)
                    used.remove(v)
        dfs(0, set(), 0)
        return best

