class Solution {
    int best = 0;
    void dfs(vector<vector<int>>& g, int r, unordered_set<int>& used, int acc) {
        if (r == (int)g.size()) { best = max(best, acc); return; }
        dfs(g, r + 1, used, acc);
        unordered_set<int> seen;
        for (int v : g[r])
            if (!used.count(v) && seen.insert(v).second) {
                used.insert(v);
                dfs(g, r + 1, used, acc + v);
                used.erase(v);
            }
    }
public:
    int maxScore(vector<vector<int>>& grid) {
        unordered_set<int> used;
        dfs(grid, 0, used, 0);
        return best;
    }
};

