class Solution {
    private int best = 0;
    private void dfs(List<List<Integer>> g, int r, Set<Integer> used, int acc) {
        if (r == g.size()) { best = Math.max(best, acc); return; }
        dfs(g, r + 1, used, acc);
        Set<Integer> seen = new HashSet<>();
        for (int v : g.get(r))
            if (!used.contains(v) && seen.add(v)) {
                used.add(v);
                dfs(g, r + 1, used, acc + v);
                used.remove(v);
            }
    }
    public int maxScore(List<List<Integer>> grid) {
        dfs(grid, 0, new HashSet<>(), 0);
        return best;
    }
}

