var maxScore = function(grid) {
    let best = 0;
    const dfs = (r, used, acc) => {
        if (r === grid.length) { best = Math.max(best, acc); return; }
        dfs(r + 1, used, acc);
        const seen = new Set();
        for (const v of grid[r])
            if (!used.has(v) && !seen.has(v)) {
                seen.add(v);
                used.add(v);
                dfs(r + 1, used, acc + v);
                used.delete(v);
            }
    };
    dfs(0, new Set(), 0);
    return best;
};
